package io.knowledgebrain.learning;
import java.io.IOException;
import java.util.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import io.micrometer.core.instrument.MeterRegistry;

@RestController
@ConditionalOnProperty(name="brain.learning.api.enabled",havingValue="true")
@RequestMapping("/api/spaces/{spaceId}/roadmaps/{roadmapId}/media-evidence")
final class MediaEvidenceController {
 private final MediaEvidenceStore store;private final RoadmapController authority;private final MediaReferenceClient content;private final MeterRegistry metrics;
 MediaEvidenceController(MediaEvidenceStore store,RoadmapController authority,MediaReferenceClient content,MeterRegistry metrics){this.store=store;this.authority=authority;this.content=content;this.metrics=metrics;}
 private static UUID id(String raw){return RoadmapGraph.id(raw);}
 private UUID auth(String space,HttpServletRequest r,boolean write,String trace){return authority.authorize(id(space),r,write,trace);}
 private static void query(HttpServletRequest r,Set<String> allowed){RoadmapController.parameters(r,allowed);}
 private void count(String op){metrics.counter("brain.learning.media.evidence","operation",op).increment();}
 private static String token(HttpServletRequest r){String token=null;if(r.getCookies()!=null)for(var c:r.getCookies())if(c.getName().equals("__Host-brain_guest")){if(token!=null)throw LearningStudyStore.bad();token=c.getValue();}return token;}
 private static ResponseEntity<MediaEvidenceStore.Evidence> response(MediaEvidenceStore.Evidence e){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag(LearningStudyController.tag("me",e.version())).body(e);}
 @GetMapping ResponseEntity<MediaEvidenceStore.Page> page(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r){query(r,Set.of("after","limit"));UUID roadmap=id(roadmapId),after=r.getParameter("after")==null?null:id(r.getParameter("after"));int limit=(int)RoadmapController.number(r.getParameter("limit"),20,100);auth(spaceId,r,false,RoadmapController.parent(r));count("catalog");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.page(id(spaceId),roadmap,after,limit));}
 @PostMapping ResponseEntity<MediaEvidenceStore.Evidence> link(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r)throws IOException{query(r,Set.of());UUID roadmap=id(roadmapId);String trace=RoadmapController.parent(r);UUID actor=auth(spaceId,r,true,trace);var keys=Collections.list(r.getHeaders("Idempotency-Key"));if(keys.size()!=1||!keys.getFirst().matches("[0-9a-f]{32}"))throw LearningStudyStore.bad();var body=authority.body(r,65536);if(body.size()!=4||!body.path("nodeId").isString()||!body.path("mediaId").isString()||!body.path("mediaVersion").isIntegralNumber()||!body.path("mediaVersion").canConvertToLong()||!body.path("memo").isString())throw LearningStudyStore.bad();var input=new MediaEvidenceStore.Input(id(body.path("nodeId").asString()),id(body.path("mediaId").asString()),body.path("mediaVersion").asLong(),body.path("memo").asString());var result=store.record(id(spaceId),roadmap,actor,keys.getFirst(),input,trace.substring(3,35),()->content.check(id(spaceId),input.mediaId(),actor,input.mediaVersion(),token(r),trace));count(result.created()?"linked":"replayed");return ResponseEntity.status(result.created()?201:200).header("Location",r.getRequestURI()+"/"+result.evidence().evidenceId()).eTag(LearningStudyController.tag("me",result.evidence().version())).cacheControl(CacheControl.noStore()).body(result.evidence());}
 @GetMapping("/{evidenceId}") ResponseEntity<MediaEvidenceStore.Evidence> get(@PathVariable String spaceId,@PathVariable String roadmapId,@PathVariable String evidenceId,HttpServletRequest r){query(r,Set.of());UUID roadmap=id(roadmapId),evidence=id(evidenceId);auth(spaceId,r,false,RoadmapController.parent(r));count("read");return response(store.get(id(spaceId),roadmap,evidence));}
 @PutMapping("/{evidenceId}") ResponseEntity<MediaEvidenceStore.Evidence> edit(@PathVariable String spaceId,@PathVariable String roadmapId,@PathVariable String evidenceId,HttpServletRequest r)throws IOException{query(r,Set.of());UUID roadmap=id(roadmapId),evidence=id(evidenceId);String trace=RoadmapController.parent(r);UUID actor=auth(spaceId,r,true,trace);long version=LearningStudyController.version(r,"me",false);var body=authority.body(r,65536);if(body.size()!=1||!body.path("memo").isString())throw LearningStudyStore.bad();var value=store.change(id(spaceId),roadmap,evidence,actor,version,body.path("memo").asString(),false,trace.substring(3,35));count("edit");return response(value);}
 @DeleteMapping("/{evidenceId}") ResponseEntity<Void> retire(@PathVariable String spaceId,@PathVariable String roadmapId,@PathVariable String evidenceId,HttpServletRequest r){query(r,Set.of());if(r.getContentLengthLong()>0||r.getHeader("Transfer-Encoding")!=null)throw LearningStudyStore.bad();UUID roadmap=id(roadmapId),evidence=id(evidenceId);String trace=RoadmapController.parent(r);UUID actor=auth(spaceId,r,true,trace);var value=store.change(id(spaceId),roadmap,evidence,actor,LearningStudyController.version(r,"me",false),null,true,trace.substring(3,35));count("retire");return ResponseEntity.noContent().cacheControl(CacheControl.noStore()).eTag(LearningStudyController.tag("me",value.version())).build();}
 @GetMapping("/{evidenceId}/revisions") ResponseEntity<List<MediaEvidenceStore.Revision>> history(@PathVariable String spaceId,@PathVariable String roadmapId,@PathVariable String evidenceId,HttpServletRequest r){query(r,Set.of("before","limit"));UUID roadmap=id(roadmapId),evidence=id(evidenceId);long before=RoadmapController.number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE);int limit=(int)RoadmapController.number(r.getParameter("limit"),5,10);auth(spaceId,r,false,RoadmapController.parent(r));count("history");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.history(id(spaceId),roadmap,evidence,before,limit));}
}
